syntax:
class MyClass {
    // Compiler-synthesized default constructor: 
    // MyClass() : base_class(), member1(), member2() {}  // Implicitly generated if not defined
    int member1;  // Built-in type, default-initialized (indeterminate in C++03, zero-initialized in C++11+ if in mem-init list)
    std::string member2;  // Class type, invokes std::string::string()
    MyClass() = default;  // Explicitly requests synthesis, but compiler may still optimize
};

code_example:
#include <iostream>
#include <string>
class Base {
public:
    Base() { std::cout << "Base default constructor" << std::endl; }  // Base class constructor
};
class Derived : public Base {
public:
    std::string str;  // Member of class type
    int num;  // Built-in member
    // No explicit default constructor; compiler synthesizes one
};
int main() {
    Derived obj;  // Invokes synthesized Derived::Derived(), which calls Base::Base() and default-constructs str
    return 0;
}
